var t=`1352-hornado`;var r=`world-1352`;var o=`EC`;var i=`south-america`;var a=4;var s=279;var d={en:`Hornado`,ua:`Орнадо`};var g={en:`Hornado is a dish from Ecuador featuring pork leg, garlic, potato, red onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Орнадо, страва кухні країни Еквадор з такими основними складниками: свинячий окіст, часник, картопля, червона цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`pork-leg`,1350,`g`],[`garlic`,7,`clove`],[`ground-cumin`,8,`g`],[`light-beer`,270,`ml`]]},{en:`Roast the already seasoned food in a preheated oven until tender and safely cooked, using a thermometer for meat or poultry.`,ua:`Запікайте вже приправлені продукти в розігрітій духовці до м’якості та готовності, перевіряючи температуру м’яса термометром.`,t:[`roasting`],m:175,i:[]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:10,i:[]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`potato`,450,`g`],[`red-onion`,190,`g`],[`cilantro`,25,`g`]]}];var h={slug:t,id:r,country:`EC`,region:i,servings:4,minutes:279,title:d,text:g,steps:l};export{o as country,h as default,r as id,s as minutes,i as region,a as servings,t as slug,l as steps,g as text,d as title};